<?php
namespace App\Controllers;
use CodeIgniter\Controller;
use Config\Database;
class Reports extends Controller{
 private function guard(){return \App\Services\PermissionService::allows('REPORT_VIEW')?null:$this->response->setStatusCode(403)->setBody('Forbidden');}
 public function index(){if($r=$this->guard())return $r;$db=Database::connect();$loc=(int)session()->get('location_id');$today=date('Y-m-d');$from=trim((string)$this->request->getGet('from'))?:$today;$to=trim((string)$this->request->getGet('to'))?:$today;if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$from))$from=$today;if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$to))$to=$today;if($from>$to)[$from,$to]=[$to,$from];$sales=$db->table('sales')->select('COUNT(*) count,SUM(total_amount) total,SUM(credit_amount) credit')->where(['location_id'=>$loc,'status'=>'posted'])->where(\App\Services\SalesService::revenueSaleCondition(),null,false)->where('transaction_at >=',$from.' 00:00:00')->where('transaction_at <=',$to.' 23:59:59')->get()->getRowArray();$saleRows=$db->table('sales s')->select('s.id,s.sale_no,s.transaction_at,s.transaction_type,s.total_amount,s.credit_amount,c.name customer_name,u.full_name created_by_name')->join('customers c','c.id=s.customer_id','left')->join('users u','u.id=s.created_by','left')->where(['s.location_id'=>$loc,'s.status'=>'posted'])->where(\App\Services\SalesService::revenueSaleCondition('s'),null,false)->where('s.transaction_at >=',$from.' 00:00:00')->where('s.transaction_at <=',$to.' 23:59:59')->orderBy('s.transaction_at','DESC')->orderBy('s.id','DESC')->get()->getResultArray();$purchases=$db->table('purchases')->select('COUNT(*) count,SUM(total_amount) total,SUM(credit_amount) credit')->where(['location_id'=>$loc,'status'=>'posted'])->where('transaction_at >=',$from.' 00:00:00')->where('transaction_at <=',$to.' 23:59:59')->get()->getRowArray();$payments=$db->table('sale_payments sp')->select('payment_mode,SUM(amount) amount')->join('sales s','s.id=sp.sale_id')->where('s.location_id',$loc)->where('s.status','posted')->where('sp.payment_type','sale')->where(\App\Services\SalesService::revenueSaleCondition('s'),null,false)->where('sp.payment_at >=',$from.' 00:00:00')->where('sp.payment_at <=',$to.' 23:59:59')->groupBy('payment_mode')->get()->getResultArray();$deposits=$db->table('customer_security_deposits')->select("SUM(CASE WHEN entry_type='hold' THEN amount ELSE 0 END) held,SUM(CASE WHEN entry_type='refund' THEN amount ELSE 0 END) refunded")->where(['location_id'=>$loc])->where('transaction_at >=',$from.' 00:00:00')->where('transaction_at <=',$to.' 23:59:59')->get()->getRowArray();$depositBalance=$db->table('customer_security_deposits')->select("SUM(CASE WHEN entry_type='hold' THEN amount ELSE -amount END) balance")->where(['location_id'=>$loc])->get()->getRowArray();return view('reports/index',['title'=>'Reports','sales'=>$sales,'saleRows'=>$saleRows,'purchases'=>$purchases,'payments'=>$payments,'today'=>$today,'from'=>$from,'to'=>$to,'deposits'=>$deposits,'depositBalance'=>(float)($depositBalance['balance']??0)]);}
 public function custody(){if($r=$this->guard())return $r;$db=Database::connect();$loc=(int)session()->get('location_id');$rows=$db->table('cylinder_custody cc')->select('cc.*,c.code customer_code,c.name customer_name,c.phone customer_phone,cu.unit_code,cu.gas_weight_kg,ct.code cylinder_code,ct.name cylinder_name')->join('customers c','c.id=cc.customer_id')->join('cylinder_units cu','cu.id=cc.cylinder_unit_id')->join('cylinder_types ct','ct.id=cu.cylinder_type_id')->where(['cc.location_id'=>$loc,'cc.status'=>'issued'])->orderBy('c.name')->orderBy('cu.unit_code')->get()->getResultArray();$totals=$db->table('customer_security_deposits')->select("SUM(CASE WHEN entry_type='hold' THEN amount ELSE -amount END) balance")->where(['location_id'=>$loc])->get()->getRowArray();return view('reports/custody',['title'=>'Cylinder Custody & Security Deposits','rows'=>$rows,'depositBalance'=>(float)($totals['balance']??0)]);}
 public function inventoryDetail(){if($r=$this->guard())return $r;$db=Database::connect();$loc=(int)session()->get('location_id');$types=$db->table('cylinder_types')->where('is_active',1)->orderBy('sort_order')->get()->getResultArray();$summary=[];$partials=[];$companyTotalGas=0.0;$companyFilled=0;$companyEmpty=0;foreach($types as $t){$typeId=(int)$t['id'];$filled=$db->table('cylinder_units')->where(['location_id'=>$loc,'cylinder_type_id'=>$typeId,'status'=>'filled'])->get()->getResultArray();$empty=(int)$db->table('cylinder_units')->where(['location_id'=>$loc,'cylinder_type_id'=>$typeId,'status'=>'empty'])->countAllResults();$gas=array_sum(array_map(static fn($u)=>(float)$u['gas_weight_kg'],$filled));$summary[]=['id'=>$typeId,'code'=>$t['code'],'name'=>$t['name'],'capacity_kg'=>(float)$t['capacity_kg'],'filled_cylinders'=>count($filled),'empty_cylinders'=>$empty,'filled_gas_kg'=>$gas,'partial_cylinders'=>0];$companyFilled+=count($filled);$companyEmpty+=$empty;$companyTotalGas+=$gas;foreach($filled as $u){$remaining=(float)$u['gas_weight_kg'];$capacity=(float)$t['capacity_kg'];if($remaining>0.00001&&$remaining<$capacity-0.00001){$partials[]=['unit_code'=>$u['unit_code'],'type_code'=>$t['code'],'type_name'=>$t['name'],'capacity_kg'=>$capacity,'gas_weight_kg'=>$remaining,'used_kg'=>max(0,$capacity-$remaining),'used_percent'=>$capacity>0?max(0,min(100,(($capacity-$remaining)/$capacity)*100)):0,'updated_at'=>$u['updated_at']??$u['created_at']];$summary[array_key_last($summary)]['partial_cylinders']++;}}}usort($partials,static fn($a,$b)=>strcmp($a['type_code'].'|'.$a['unit_code'],$b['type_code'].'|'.$b['unit_code']));return view('reports/inventory_detail',['title'=>'Inventory Detail Report','summary'=>$summary,'partials'=>$partials,'companyTotalGas'=>$companyTotalGas,'companyFilled'=>$companyFilled,'companyEmpty'=>$companyEmpty]);}
 public function stock(){if($r=$this->guard())return $r;return redirect()->to('/inventory');}
 public function ledger(int $customerId){if($r=$this->guard())return $r;$db=Database::connect();$loc=(int)session()->get('location_id');$c=$db->table('customers')->where('id',$customerId)->get()->getRowArray();if(!$c)return $this->response->setStatusCode(404)->setBody('Customer not found');$sales=$db->table('sales')->where(['customer_id'=>$customerId,'status'=>'posted'])->where('location_id',$loc)->orderBy('transaction_at')->get()->getResultArray();$receipts=$db->table('customer_receipts')->where(['customer_id'=>$customerId,'status'=>'posted'])->where('location_id',$loc)->orderBy('receipt_at')->get()->getResultArray();$events=[];foreach($sales as $s){$events[]=['date'=>$s['transaction_at'],'type'=>'Sale OS','reference'=>$s['sale_no'],'debit'=>(float)$s['credit_amount'],'credit'=>0.0];}foreach($receipts as $rr){$events[]=['date'=>$rr['receipt_at'],'type'=>'Receipt / OS Settlement','reference'=>$rr['receipt_no'],'debit'=>0.0,'credit'=>(float)$rr['amount']];}usort($events,static fn($a,$b)=>strcmp($a['date'].'|'.$a['reference'],$b['date'].'|'.$b['reference']));$running=(float)$c['opening_balance'];foreach($events as &$e){$running+=(float)$e['debit']-(float)$e['credit'];$e['running_balance']=$running;}unset($e);$settings=(new \App\Models\ShopSettingsModel())->forLocation($loc);$mode=$settings['credit_limit_validation_mode']??'none';$limit=$mode==='shop'?(float)($settings['shop_credit_limit']??0):(float)$c['credit_limit'];return view('reports/ledger',['title'=>'Customer Ledger','customer'=>$c,'events'=>$events,'openingBalance'=>(float)$c['opening_balance'],'creditLimitMode'=>$mode,'effectiveCreditLimit'=>$limit,'currentBalance'=>$running]);}
}